const columns=[{index:0,label:'Номер',visible:true},{index:1,label:'Дата',visible:true},{index:2,label:'Сумма в валюте платежа, ₽',visible:true},{index:3,label:'Сумма НДС, ₽',visible:true},{index:4,label:'Назначение платежа',visible:true}];
let order=[...columns],sortIndex=0,ascending=true,rangeStart='2026-01-01',rangeEnd='2026-09-09';
const head=document.querySelector('#documentsHead'),body=document.querySelector('#documentsRows');
const parseMoney=v=>Number(v.replace(/\s/g,'').replace(',','.'))||0;
const priceValue=v=>new Intl.NumberFormat('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2}).format(parseMoney(v));
const monthIndexes={янв:0,фев:1,мар:2,апр:3,май:4,июн:5,июл:6,авг:7,сен:8,окт:9,ноя:10,дек:11};
const parseDate=v=>{const [day,month,year]=v.split(' ');return new Date(Number(year),monthIndexes[month],Number(day)).getTime()};
const dateToIso=v=>{const date=new Date(parseDate(v));return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`};
const render=()=>{const visible=order.filter(c=>c.visible);const grid=visible.map(c=>['126px','90px','210px','120px','minmax(360px,1fr)'][c.index]).join(' ');const rows=[...sourceDocuments].filter(r=>{const d=dateToIso(r[1]);return d>=rangeStart&&d<=rangeEnd}).sort((a,b)=>{let av=a[sortIndex],bv=b[sortIndex];if(sortIndex===1){av=parseDate(av);bv=parseDate(bv)}else if(sortIndex===2||sortIndex===3){av=parseMoney(av);bv=parseMoney(bv)}else return (ascending?1:-1)*av.localeCompare(bv,'ru');return (ascending?1:-1)*(av-bv)});head.style.gridTemplateColumns=grid;head.innerHTML=visible.map(c=>`<span>${c.label}</span>`).join('');body.innerHTML=rows.map(r=>`<div class="documents-row" style="grid-template-columns:${grid}">${visible.map(c=>`<span>${c.index===2||c.index===3?priceValue(r[c.index]):r[c.index]}</span>`).join('')}</div>`).join('')};render();
document.querySelectorAll('.doc-select>button').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();const select=button.closest('.doc-select');document.querySelectorAll('.doc-select.is-open').forEach(x=>{if(x!==select){x.classList.remove('is-open');x.querySelector(':scope>button').setAttribute('aria-expanded','false')}});const open=select.classList.toggle('is-open');button.setAttribute('aria-expanded',String(open))}));
document.addEventListener('click',e=>{const option=e.target.closest('.doc-menu button');if(option){const select=option.closest('.doc-select');select.querySelector(':scope>button span').textContent=option.textContent;select.classList.remove('is-open');select.querySelector(':scope>button').setAttribute('aria-expanded','false');if(option.dataset.sort){sortIndex={number:0,date:1,amount:2,vat:3,purpose:4}[option.dataset.sort];render()}if(option.dataset.direction){ascending=option.dataset.direction==='asc';render()}}document.querySelectorAll('.doc-select.is-open').forEach(x=>{x.classList.remove('is-open');x.querySelector(':scope>button').setAttribute('aria-expanded','false')});if(!e.target.closest('.doc-date')){document.querySelector('#documentsCalendar').hidden=true;document.querySelector('#dateRangeButton').setAttribute('aria-expanded','false')}});
const months=['Январь','Февраль','Март','Апрель','Май','Июнь','Июль','Август','Сентябрь','Октябрь','Ноябрь','Декабрь'];const iso=(m,d)=>`2026-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;const calendar=document.querySelector('#documentsCalendar');let visibleMonth=0;const drawCalendar=(month=visibleMonth)=>{visibleMonth=month;const first=(new Date(2026,month,1).getDay()+6)%7,count=new Date(2026,month+1,0).getDate();const dates=Array.from({length:count},(_,i)=>{const day=i+1,date=iso(month,day),weekday=(first+i)%7,classes=[date===rangeStart?'range-start':'',date===rangeEnd?'range-end':'',date>rangeStart&&date<rangeEnd?'in-range':'',weekday===0?'week-start':'',weekday===6?'week-end':'',day===1?'month-start':'',day===count?'month-end':'',weekday>=5?'weekend':''].filter(Boolean).join(' ');return `<button type="button" data-date="${date}" class="${classes}"><span>${day}</span></button>`}).join('');calendar.innerHTML=`<div class="calendar-picker"><div class="calendar-months" aria-label="Месяц">${months.map((name,index)=>`<button type="button" class="${index===month?'selected':''}" data-month="${index}">${name}</button>`).join('')}</div><div class="calendar-main"><div class="calendar-week"><span>пн</span><span>вт</span><span>ср</span><span>чт</span><span>пт</span><span class="weekend">сб</span><span class="weekend">вс</span></div><div class="calendar-scroll"><section><b>${months[month]} 2026</b><div class="calendar-days">${'<i></i>'.repeat(first)}${dates}</div></section></div></div></div>`};drawCalendar();
const shortMonths=['янв','фев','мар','апр','май','июн','июл','авг','сен','окт','ноя','дек'];const format=(iso,includeYear=true)=>{const [year,month,day]=iso.split('-').map(Number);return `${day} ${shortMonths[month-1]}${includeYear?` ${year}`:''}`};const formatRange=(start,end)=>end?`${format(start,start.slice(0,4)!==end.slice(0,4))} – ${format(end)}`:format(start);const dateRangeButton=document.querySelector('#dateRangeButton');const setCalendarOpen=open=>{calendar.hidden=!open;dateRangeButton.setAttribute('aria-expanded',String(open))};dateRangeButton.addEventListener('click',e=>{e.stopPropagation();setCalendarOpen(calendar.hidden)});calendar.addEventListener('click',e=>{e.stopPropagation();const month=e.target.closest('[data-month]');if(month){drawCalendar(Number(month.dataset.month));return}const day=e.target.closest('[data-date]');if(!day)return;const value=day.dataset.date;if(!rangeStart||rangeEnd){rangeStart=value;rangeEnd=''}else if(value<rangeStart){rangeEnd=rangeStart;rangeStart=value}else rangeEnd=value;dateRangeButton.querySelector('span').textContent=formatRange(rangeStart,rangeEnd);drawCalendar(visibleMonth)});
const toast=text=>{const el=document.querySelector('#documentsToast');el.textContent=text;el.classList.add('show');clearTimeout(window.docToast);window.docToast=setTimeout(()=>el.classList.remove('show'),1800)};document.querySelector('#showDocuments').addEventListener('click',()=>{if(!rangeEnd)rangeEnd=rangeStart;render();calendar.hidden=true;toast('Список документов обновлён')});document.querySelector('#exportDocuments').addEventListener('click',()=>toast('Демо: подготовка Excel-файла'));
document.querySelector('#documentsSortDirection').addEventListener('click',event=>{ascending=!ascending;event.currentTarget.querySelector('span').textContent=ascending?'По возрастанию':'По убыванию';render()});
const overlay=document.querySelector('#documentsOverlay'),list=document.querySelector('#documentsColumns');let draft=[];const drawPanel=()=>list.innerHTML=draft.map(c=>`<div class="documents-panel__row" draggable="true" data-index="${c.index}"><label><input type="checkbox" ${c.visible?'checked':''}><span>${c.label}</span></label><img class="documents-panel__drag" src="assets/sorting-default-20.svg" alt="Перетащить"></div>`).join('');document.querySelector('#configureDocuments').addEventListener('click',()=>{draft=order.map(c=>({...c}));drawPanel();overlay.hidden=false});document.querySelector('#closeDocumentsPanel').addEventListener('click',()=>overlay.hidden=true);overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.hidden=true});list.addEventListener('change',e=>{const c=draft.find(x=>x.index===Number(e.target.closest('[data-index]').dataset.index));if(c)c.visible=e.target.checked});let dragged=null;list.addEventListener('dragstart',e=>{dragged=e.target.closest('[data-index]')});list.addEventListener('dragover',e=>{e.preventDefault();const row=e.target.closest('[data-index]');if(row&&dragged&&row!==dragged)list.insertBefore(dragged,row)});list.addEventListener('dragend',()=>{draft=[...list.querySelectorAll('[data-index]')].map(row=>draft.find(c=>c.index===Number(row.dataset.index)));dragged=null});document.querySelector('#saveDocumentsColumns').addEventListener('click',()=>{if(!draft.some(c=>c.visible)){toast('Оставьте хотя бы одну колонку');return}order=draft;render();overlay.hidden=true});
